def parse_duration(s: str) -> int:
    total_seconds = 0
    parts = s.split('h')
    for part in parts:
        if part.split('m')[0] == '':
            continue
        time_unit = part.split('m')[1]
        if time_unit == 's':
            total_seconds += int(part)
        elif time_unit == 'm':
            total_seconds += int(part) * 60
        elif time_unit == 'h':
            total_seconds += int(part) * 3600
    return total_seconds
```

