def semver_cmp(a: str, b: str) -> int:
    a_parts = list(map(int, a.split('.')))
    b_parts = list(map(int, b.split('.')))

    min_len = min(len(a_parts), len(b_parts))

    for i in range(min_len):
        if a_parts[i] < b_parts[i]:
            return -1
        elif a_parts[i] > b_parts[i]:
            return 1

    if len(a_parts) < len(b_parts):
        return -1
    elif len(a_parts) > len(b_parts):
        return 1
    else:
        return 0
```

